parameters.messages:
=[{
  'role': 'system',
  'content': $input.first().json.systemPrompt
}, {
  'role': 'user',
  'content': `Original Plan: ${JSON.stringify($input.first().json.plan)}\n\nDraft Content: ${$input.first().json.postContent}\n\nPlease review and improve this LinkedIn post.`
}]

parameters.functionCode:
const response = $input.first().json.choices[0].message.content;

try {
  const review = JSON.parse(response);
  return {
    ...review,
    chatId: $input.first().json.chatId
  };
} catch (e) {
  // Fallback
  return {
    finalContent: response,
    improvements: ['Grammar check', 'Flow improvement'],
    engagementScore: 8,
    readabilityScore: 8,
    recommendations: ['Add more specific examples', 'Include a question'],
    chatId: $input.first().json.chatId,
    rawResponse: response
  };
}
